219	  private async pump(): Promise<void> {
220	    try {
221	      for await (const message of this.query) {
222	        this.options.trace?.(describeMessage(message))
223	        for (const event of this.mapper.map(message)) {
224	          if (event.type === 'session_started') this.engineSessionId = event.engineSessionId
225	          this.output.push(event)
226	        }
227	      }
228	    } catch (error) {
229	      if (!this.abort.signal.aborted) {
230	        this.output.push({ type: 'error', message: errorMessage(error), fatal: true })
231	      }
232	    } finally {
233	      this.denyAllPending('Session ended')
234	      this.finish()
235	    }
236	  }
237	
238	  private finish(): void {
239	    if (this.output.isEnded) return
240	    this.output.push({ type: 'ended' })
241	    this.output.end()
242	  }
243	}
