245	/**
246	 * The engine validates an allow as `{ updatedInput: record }`, so the
247	 * unchanged input is echoed back; the typings mark it optional but the
248	 * CLI does not.
249	 */
250	function toPermissionResult(decision: PermissionDecision, input: Record<string, unknown>): PermissionResult {
251	  switch (decision.kind) {
252	    case 'allow':
253	      return { behavior: 'allow', updatedInput: input, decisionClassification: 'user_temporary' }
254	    case 'deny':
255	      return { behavior: 'deny', message: decision.message ?? 'Denied by user', decisionClassification: 'user_reject' }
256	  }
257	}
258	
259	function errorMessage(error: unknown): string {
260	  return error instanceof Error ? error.message : String(error)
261	}
