263	/** One line per engine message: kind, and for stream events the raw event and delta kinds. */
264	export function describeMessage(msg: SDKMessage): string {
265	  switch (msg.type) {
266	    case 'stream_event': {
267	      const event = msg.event as { type: string; delta?: { type?: string }; content_block?: { type?: string } }
268	      const detail = event.delta?.type ?? event.content_block?.type
269	      return `stream_event ${event.type}${detail ? ` ${detail}` : ''}`
270	    }
271	    case 'system':
272	      return `system ${msg.subtype}${'status' in msg ? ` ${String(msg.status)}` : ''}`
273	    case 'assistant':
274	      return `assistant [${msg.message.content.map((b) => b.type).join(', ')}]`
275	    case 'user': {
276	      const content = msg.message.content
277	      return `user ${typeof content === 'string' ? 'text' : `[${content.map((b) => b.type).join(', ')}]`}`
278	    }
279	    case 'result':
280	      return `result ${msg.subtype} ${msg.duration_ms}ms`
281	    default:
282	      return msg.type
283	  }
284	}
