/** Collects events until `count` have arrived. */
async function take(session: SdkSession, count: number): Promise<SessionEvent[]> {
  const out: SessionEvent[] = []
  for await (const e of session.events()) {
    out.push(e)
    if (out.length === count) break
  }
  return out
}

