    expect(event).toEqual({ type: 'user_message', text: 'fix the bug' })
    await tick()
    expect(fake.received).toEqual([
      { type: 'user', message: { role: 'user', content: 'fix the bug' }, parent_tool_use_id: null },
    ])
    await session.dispose()
  })

