import * as vscode from 'vscode'
import type { SessionManager, SessionMode, SessionRecord } from '../agent/session/session-manager'
import type { SessionStatus } from '../agent/session/session-status'

const MODE_LABEL: Record<SessionMode, string> = { chat: 'Chat', plan: 'Plan', reconcile: 'Map against code', implement: 'Implement' }

const STATUS_ICON: Record<SessionStatus, { icon: string; color?: string }> = {
  idle: { icon: 'circle-outline' },
  planning: { icon: 'checklist', color: 'charts.blue' },
  implementing: { icon: 'tools', color: 'charts.blue' },
  needs_human: { icon: 'person', color: 'charts.orange' },
  error: { icon: 'error', color: 'charts.red' },
}

/** The Sessions view: every session, with its status; click opens it in the chat. */
export class SessionsTree implements vscode.TreeDataProvider<SessionRecord> {
  private readonly changed = new vscode.EventEmitter<void>()
  readonly onDidChangeTreeData = this.changed.event

  constructor(
    private readonly sessions: SessionManager,
    private readonly activeId: () => string | undefined,
    private readonly statusOf: (sessionId: string) => SessionStatus,
  ) {}

  refresh(): void {
    this.changed.fire()
  }

  /** A run under another session (a check) shows on its parent, not as an entry of its own. */
  getChildren(): SessionRecord[] {
    return this.sessions.list().filter((r) => !r.parentId)
  }

  getTreeItem(record: SessionRecord): vscode.TreeItem {
    const item = new vscode.TreeItem(record.title)
    const status = this.statusOf(record.id)
    const active = record.id === this.activeId()
    const { icon, color } = STATUS_ICON[status]
    item.id = record.id
    item.description = `${record.profile.name} · ${status.replace('_', ' ')}${active ? ' · open' : ''}`
    item.iconPath = new vscode.ThemeIcon(icon, color ? new vscode.ThemeColor(color) : undefined)
    item.tooltip = `${MODE_LABEL[record.mode]} · ${record.profile.name} · ${status.replace('_', ' ')}`
    item.contextValue = 'session'
    item.command = { command: 'kiwiAgent.openSession', title: 'Open Session', arguments: [record.id] }
    return item
  }
}
import { compileTemplate } from '@relax.js/core/html'
import type { SessionTab } from '../protocol'
import type { SessionStatus } from '../../agent/session/session-status'
import { NewSessionViewRequestedEvent, SessionClosedEvent, SessionSelectedEvent } from './events'

const STATUS: Record<SessionStatus, { icon: string; label: string }> = {
  idle: { icon: '○', label: 'waiting for you' },
  planning: { icon: '📐', label: 'planning' },
  implementing: { icon: '🔧', label: 'implementing' },
  needs_human: { icon: '✋', label: 'needs you' },
  error: { icon: '⚠', label: 'error' },
}

type TabRow = SessionTab & { icon: string; label: string; state: string }

/** Tabs for the sessions in play plus "+". Parent supplies the data; clicks become events. */
export class SessionTabs extends HTMLElement {
  private readonly template = compileTemplate(`
    <ul class="tabs">
      <li loop="t in tabs" class="tab {{t.status}} {{t.state}}" title="{{t.title}} · {{t.profileName}} · {{t.label}}" r-click="select(t)">
        <span class="status">{{t.icon}}</span>
        <span class="title">{{t.title}}</span>
        <button type="button" class="close" title="Stop engine and hide tab" r-click="close(t, event)">×</button>
      </li>
      <li class="tab new {{newState}}" title="New session" r-click="add()">+</li>
    </ul>
  `)

  connectedCallback(): void {
    if (this.childElementCount === 0) this.appendChild(this.template.content)
  }

  update(tabs: SessionTab[], creating: boolean): void {
    const rows: TabRow[] = tabs.map((t) => ({
      ...t,
      ...STATUS[t.status],
      state: t.active && !creating ? 'active' : '',
    }))
    this.template.render(
      { tabs: rows, newState: creating ? 'active' : '' },
      {
        select: (t: TabRow) => this.dispatchEvent(new SessionSelectedEvent(t.id)),
        close: (t: TabRow, event: Event) => {
          event.stopPropagation()
          this.dispatchEvent(new SessionClosedEvent(t.id))
        },
        add: () => this.dispatchEvent(new NewSessionViewRequestedEvent()),
      },
    )
  }
}

customElements.define('session-tabs', SessionTabs)

