1	/**
2	 * Unbounded producer/consumer queue exposed as an async iterable.
3	 * One consumer at a time. `end()` lets the consumer drain and then finish;
4	 * `fail()` rejects the consumer's next read.
5	 */
6	export class AsyncQueue<T> implements AsyncIterable<T> {
7	  private readonly buffer: T[] = []
8	  private waiter: { resolve: (r: IteratorResult<T>) => void; reject: (e: unknown) => void } | undefined
9	  private ended = false
10	  private failure: unknown
11	
12	  push(item: T): void {
13	    if (this.ended) throw new Error('AsyncQueue: push after end')
14	    if (this.waiter) {
15	      const w = this.waiter
16	      this.waiter = undefined
17	      w.resolve({ value: item, done: false })
18	      return
19	    }
20	    this.buffer.push(item)
21	  }
22	
23	  end(): void {
24	    if (this.ended) return
25	    this.ended = true
26	    if (this.waiter) {
27	      const w = this.waiter
28	      this.waiter = undefined
29	      w.resolve({ value: undefined, done: true })
30	    }
31	  }
32	
33	  fail(error: unknown): void {
34	    if (this.ended) return
35	    this.failure = error
36	    this.ended = true
37	    if (this.waiter) {
38	      const w = this.waiter
39	      this.waiter = undefined
40	      w.reject(error)
41	    }
42	  }
43	
44	  get isEnded(): boolean {
45	    return this.ended
46	  }
47	
48	  [Symbol.asyncIterator](): AsyncIterator<T> {
49	    return {
50	      next: () => {
51	        const item = this.buffer.shift()
52	        if (item !== undefined) return Promise.resolve({ value: item, done: false })
53	        if (this.failure !== undefined) return Promise.reject(this.failure)
54	        if (this.ended) return Promise.resolve({ value: undefined, done: true })
55	        if (this.waiter) return Promise.reject(new Error('AsyncQueue: concurrent consumers'))
56	        return new Promise((resolve, reject) => {
57	          this.waiter = { resolve, reject }
58	        })
59	      },
60	      // A consumer leaving a `for await` early does not close the queue: it
61	      // is a live stream, and the consumer may come back for the rest.
62	      return: () => Promise.resolve({ value: undefined, done: true }),
63	    }
64	  }
65	}
